import re

def normalize_manifest_entry(raw: str) -> str:
    """Collapse duplicate slashes and reject '..' or absolute paths with ValueError."""
    cleaned = re.sub(r'/+', '/', raw.replace('\\', '/').strip())
    if not cleaned or cleaned.startswith('/') or re.match(r'^[A-Za-z]:', cleaned):
        raise ValueError(f'Invalid manifest path: {raw!r}')
    parts = [p for p in cleaned.split('/') if p and p != '.']
    if not parts or any(p == '..' for p in parts):
        raise ValueError(f'Traversal segment forbidden: {raw!r}')
    return '/'.join(parts)

