from pkg_ar02.node import TreeNode

def collect_bounded_nodes(root: TreeNode, max_depth: int) -> list[str]:
    """Enforce max_depth inclusively and skip visited node_ids to prevent graph cycles."""
    if max_depth < 0:
        return []
    out: list[str] = []
    visited: set[str] = set()
    def _dfs(cur: TreeNode, depth: int) -> None:
        if depth > max_depth or cur.node_id in visited:
            return
        visited.add(cur.node_id)
        out.append(cur.node_id)
        for ch in cur.children:
            _dfs(ch, depth + 1)
    _dfs(root, 0)
    return out

