def parse_template_lines(raw: str) -> dict[str, str]:
    """Strip inline comments outside quotes and preserve empty defaults."""
    out: dict[str, str] = {}
    for raw_ln in raw.splitlines():
        ln = raw_ln.strip()
        if not ln or ln.startswith('#') or '=' not in ln:
            continue
        key, val_raw = ln.split('=', 1)
        v = val_raw.strip()
        if len(v) >= 2 and v[0] in ('"', "'") and v[-1] == v[0]:
            cleaned = v[1:-1]
        else:
            cleaned = v.split('#', 1)[0].strip()
        out[key.strip()] = cleaned
    return out

def validate_required_keys(parsed: dict[str, str], required: list[str]) -> list[str]:
    """Return sorted list of required keys missing from parsed schema."""
    return [k for k in required if k not in parsed]

