import re

def glob_match_path(pattern: str, candidate: str) -> bool:
    """Escape regex metacharacters like '.' while supporting '*' and '?' within segments."""
    parts: list[str] = ['^']
    for ch in pattern.replace('\\', '/'):
        if ch == '*':
            parts.append('[^/]*')
        elif ch == '?':
            parts.append('[^/]')
        else:
            parts.append(re.escape(ch))
    parts.append('$')
    return bool(re.match(''.join(parts), candidate.replace('\\', '/')))

