def _xor_checksum(data: bytes) -> int:
    acc = 0
    for b in data:
        acc ^= b
    return acc

def encode_frame(payload: bytes) -> str:
    """Encode payload bytes with trailing 1-byte XOR checksum in hex."""
    chk = _xor_checksum(payload)
    return (payload + bytes([chk])).hex()

def decode_frame(hex_frame: str) -> bytes:
    """Decode hex frame and reject truncated or corrupted XOR checksums."""
    if not hex_frame or len(hex_frame) % 2 != 0:
        raise ValueError('Invalid hex frame length')
    raw = bytes.fromhex(hex_frame)
    if len(raw) < 1:
        raise ValueError('Empty frame')
    body, expected = raw[:-1], raw[-1]
    if _xor_checksum(body) != expected:
        raise ValueError('Frame XOR checksum mismatch')
    return body

