import unicodedata

_ZERO_WIDTH = frozenset({'\u200b', '\u200c', '\u200d', '\ufeff', '\u2060'})

def strip_invisible_controls(text: str) -> str:
    """Remove zero-width format characters and NFKC-normalize text."""
    normalized = unicodedata.normalize('NFKC', text)
    cleaned = ''.join(
        ch for ch in normalized
        if ch not in _ZERO_WIDTH and unicodedata.category(ch) != 'Cf'
    )
    return cleaned.strip()

