from collections import deque

class SlidingQuotaMeter:
    """Sliding-window event quota meter."""

    def __init__(self, max_events: int, window_sec: float) -> None:
        self.max_events = max_events
        self.window_sec = window_sec
        self._events: deque[float] = deque()

    def record_and_check(self, now: float) -> bool:
        """Prune timestamps older than now - window_sec before enforcing max_events."""
        cutoff = now - self.window_sec
        while self._events and self._events[0] <= cutoff:
            self._events.popleft()
        if len(self._events) >= self.max_events:
            return False
        self._events.append(now)
        return True

