from urllib.parse import urlparse

def parse_https_endpoint(url: str) -> tuple[str, int]:
    """Enforce https scheme, non-empty host, and explicit port range 1..65535."""
    parsed = urlparse(url.strip())
    if parsed.scheme.lower() != 'https' or not parsed.hostname:
        raise ValueError(f'HTTPS host required: {url!r}')
    try:
        raw_port = parsed.port
    except ValueError as exc:
        raise ValueError(f'Out-of-range port in {url!r}') from exc
    port = 443 if raw_port is None else int(raw_port)
    if not (1 <= port <= 65535):
        raise ValueError(f'Invalid port: {port}')
    return (parsed.hostname.lower(), port)

