import base64
import hashlib

def sha256_pem_body(pem_text: str) -> str:
    """Strip PEM armor headers and whitespace before computing SHA-256 over DER bytes."""
    body_lines = [
        ln.strip()
        for ln in pem_text.splitlines()
        if ln.strip() and not ln.strip().startswith('-----')
    ]
    joined = ''.join(body_lines)
    if not joined:
        raise ValueError('Empty PEM payload')
    der_bytes = base64.b64decode(joined.encode('ascii'), validate=True)
    if not der_bytes:
        raise ValueError('Decoded PEM payload is empty')
    return hashlib.sha256(der_bytes).hexdigest()

