def chunk_by_byte_budget(lines: list[str], max_bytes: int) -> list[list[str]]:
    """Split lines into chunks never exceeding max_bytes while preserving line order."""
    if max_bytes <= 0:
        raise ValueError('max_bytes must be positive')
    chunks: list[list[str]] = []
    cur: list[str] = []
    cur_bytes = 0
    for ln in lines:
        sz = len(ln.encode('utf-8'))
        if sz > max_bytes:
            raise ValueError('Single line exceeds max_bytes')
        if cur and cur_bytes + sz > max_bytes:
            chunks.append(cur)
            cur = [ln]
            cur_bytes = sz
        else:
            cur.append(ln)
            cur_bytes += sz
    if cur:
        chunks.append(cur)
    return chunks

