import math

class QuantileAccumulator:
    """Linear-interpolating quantile accumulator."""

    def __init__(self) -> None:
        self._vals: list[float] = []

    def add(self, val: float) -> None:
        self._vals.append(float(val))

    def percentile(self, pct: float) -> float:
        """Interpolate sorted observations cleanly and raise ValueError on empty samples."""
        if not self._vals or not (0.0 <= pct <= 100.0):
            raise ValueError('Non-empty samples and 0 <= pct <= 100 required')
        ordered = sorted(self._vals)
        if len(ordered) == 1:
            return ordered[0]
        rank = (pct / 100.0) * (len(ordered) - 1)
        lo = math.floor(rank)
        hi = math.ceil(rank)
        frac = rank - lo
        return ordered[lo] * (1.0 - frac) + ordered[hi] * frac

