import hashlib

class ContentAddressableIndex:
    """Content-addressable store verifying SHA-256 integrity."""

    def __init__(self) -> None:
        self._blobs: dict[str, bytes] = {}

    def put_blob(self, data: bytes) -> str:
        """Deduplicate blob by sha256 digest and return hex key."""
        digest = hashlib.sha256(data).hexdigest()
        self._blobs.setdefault(digest, bytes(data))
        return digest

    def verify_blob(self, digest: str) -> bool:
        """Re-hash stored bytes to detect corruption against digest."""
        raw = self._blobs.get(digest)
        if raw is None:
            return False
        return hashlib.sha256(raw).hexdigest() == digest

