def validate_migration_versions(versions: list[int]) -> list[int]:
    """Detect duplicate version numbers and non-contiguous gaps starting from 1."""
    if not versions:
        return []
    ordered = sorted(versions)
    expected = list(range(1, len(ordered) + 1))
    if ordered != expected:
        raise ValueError(f'Non-contiguous or duplicate migrations: {versions!r}')
    return ordered

