class RingBuffer:
    """Bounded FIFO ring buffer overwriting oldest slots past capacity."""

    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError('capacity must be positive')
        self.capacity = capacity
        self._slots: list[int] = [0] * capacity
        self._head = 0
        self._count = 0

    def push(self, val: int) -> None:
        """Write val into circular buffer slot, overwriting oldest past capacity."""
        idx = (self._head + self._count) % self.capacity
        if self._count < self.capacity:
            self._slots[idx] = val
            self._count += 1
        else:
            self._slots[self._head] = val
            self._head = (self._head + 1) % self.capacity

    def items(self) -> list[int]:
        """Return active elements in FIFO chronological order."""
        return [
            self._slots[(self._head + i) % self.capacity]
            for i in range(self._count)
        ]

