import hashlib

class DeterministicBloomFilter:
    """Bloom filter using Kirsch-Mitzenmacher double hashing."""

    def __init__(self, num_bits: int = 256, k_hashes: int = 4) -> None:
        if num_bits <= 0 or k_hashes <= 0:
            raise ValueError('num_bits and k_hashes must be positive')
        self.num_bits = num_bits
        self.k_hashes = k_hashes
        self._bits = bytearray((num_bits + 7) // 8)

    def _positions(self, item: str) -> list[int]:
        digest = hashlib.sha256(item.encode('utf-8')).digest()
        h1 = int.from_bytes(digest[:8], 'big')
        h2 = int.from_bytes(digest[8:16], 'big') or 1
        return [(h1 + i * h2) % self.num_bits for i in range(self.k_hashes)]

    def add(self, item: str) -> None:
        """Set all k_hashes double-hashing positions modulo num_bits."""
        for pos in self._positions(item):
            self._bits[pos // 8] |= 1 << (pos % 8)

    def might_contain(self, item: str) -> bool:
        """Check whether all k_hashes bit positions are set for item."""
        return all(
            bool(self._bits[pos // 8] & (1 << (pos % 8)))
            for pos in self._positions(item)
        )

