class CircuitBreaker:
    """Circuit breaker supporting open, half-open cooldown, and closed recovery."""

    def __init__(self, threshold: int, cooldown_sec: float, clock: Callable[[], float]) -> None:
        self.threshold = threshold
        self.cooldown_sec = cooldown_sec
        self._clock = clock
        self.failures = 0
        self.opened_at: float | None = None

    def allow_request(self) -> bool:
        """Allow calls when closed or after cooldown_sec elapses into half-open."""
        if self.opened_at is None:
            return True
        return (self._clock() - self.opened_at) >= self.cooldown_sec

    def record_success(self) -> None:
        self.failures = 0
        self.opened_at = None

    def record_failure(self) -> None:
        self.failures += 1
        if self.failures >= self.threshold:
            self.opened_at = self._clock()

