import hashlib

def compute_merkle_root(leaves: list[bytes]) -> str:
    # BUG: lacks 0x00/0x01 second-preimage prefixes and drops odd node
    if not leaves:
        return hashlib.sha256(b'').hexdigest()
    level = [hashlib.sha256(x).digest() for x in leaves]
    while len(level) > 1:
        level = [
            hashlib.sha256(level[i] + level[i + 1]).digest()
            for i in range(0, len(level) - 1, 2)
        ]
    return level[0].hex()

