import hashlib

def compute_merkle_root(leaves: list[bytes]) -> str:
    """Prefix leaf hashes with 0x00, internal hashes with 0x01, and duplicate odd nodes."""
    if not leaves:
        return hashlib.sha256(b'').hexdigest()
    level = [hashlib.sha256(b'\x00' + leaf).digest() for leaf in leaves]
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        next_level: list[bytes] = []
        for i in range(0, len(level), 2):
            next_level.append(hashlib.sha256(b'\x01' + level[i] + level[i + 1]).digest())
        level = next_level
    return level[0].hex()

