import os
from pathlib import Path

def resolve_jailed_path(jail_root: Path, user_rel: str) -> Path:
    """Block sibling-prefix confusion, symlink escapes via realpath + commonpath, and NUL bytes."""
    if not user_rel or '\x00' in user_rel:
        raise PermissionError('Invalid or NUL-containing path')
    jail_real = os.path.realpath(str(jail_root))
    raw_cand = Path(user_rel)
    if raw_cand.is_absolute():
        raise PermissionError('Absolute paths forbidden')
    cand_real = os.path.realpath(os.path.join(jail_real, user_rel))
    try:
        within = os.path.commonpath([
            os.path.normcase(jail_real),
            os.path.normcase(cand_real),
        ]) == os.path.normcase(jail_real)
    except ValueError as exc:
        raise PermissionError('Cross-volume escape') from exc
    if not within:
        raise PermissionError(f'Path escapes jail: {user_rel!r}')
    return Path(cand_real)

