import re

def validate_member_relpath(raw_name: str) -> str:
    """Block '../' traversal, Windows backslash/drive paths, and absolute paths."""
    if not raw_name or '\x00' in raw_name:
        raise PermissionError('Empty or NUL archive path')
    norm = raw_name.replace('\\', '/').strip()
    if norm.startswith('/') or re.match(r'^[A-Za-z]:', norm):
        raise PermissionError(f'Absolute or drive archive path forbidden: {raw_name!r}')
    parts = [p for p in norm.split('/') if p and p != '.']
    if not parts or any(p == '..' for p in parts):
        raise PermissionError(f'Traversal segment in archive member: {raw_name!r}')
    return '/'.join(parts)

