from contextlib import ExitStack
from pkg_ar34.account import Account

class AtomicLedger:
    """Deadlock-free multi-account ledger using canonical lock ordering."""

    def __init__(self, initial: dict[str, int]) -> None:
        self._accts = {k: Account(k, int(v)) for k, v in initial.items()}

    def balance_of(self, account_id: str) -> int:
        acct = self._accts[account_id]
        with acct.lock:
            return acct.balance

    def transfer(self, src_id: str, dst_id: str, amount: int) -> None:
        """Execute single transfer via atomic canonical lock ordering."""
        self.batch_transfer([(src_id, dst_id, amount)])

    def batch_transfer(self, legs: list[tuple[str, str, int]]) -> None:
        """Acquire locks in canonical sorted account_id order and validate balances atomically."""
        if not legs:
            return
        involved: set[str] = set()
        for src_id, dst_id, amount in legs:
            if src_id == dst_id or amount <= 0:
                raise ValueError('Self-transfer and non-positive amounts forbidden')
            if src_id not in self._accts or dst_id not in self._accts:
                raise KeyError('Unknown account_id')
            involved.update((src_id, dst_id))
        with ExitStack() as stack:
            for aid in sorted(involved):
                stack.enter_context(self._accts[aid].lock)
            staged = {aid: self._accts[aid].balance for aid in involved}
            for src_id, dst_id, amount in legs:
                if staged[src_id] < amount:
                    raise ValueError(f'Insufficient funds in {src_id}')
                staged[src_id] -= amount
                staged[dst_id] += amount
            for aid, new_bal in staged.items():
                self._accts[aid].balance = new_bal

