import ipaddress

_CGNAT_NET = ipaddress.ip_network('100.64.0.0/10')

def is_public_ip(raw_ip: str) -> bool:
    """Unwrap IPv4-mapped IPv6 addresses and block RFC1918, loopback, link-local, and CGNAT."""
    try:
        addr: ipaddress.IPv4Address | ipaddress.IPv6Address = ipaddress.ip_address(raw_ip.strip())
    except ValueError:
        return False
    if isinstance(addr, ipaddress.IPv6Address) and addr.ipv4_mapped is not None:
        addr = addr.ipv4_mapped
    if isinstance(addr, ipaddress.IPv4Address) and addr in _CGNAT_NET:
        return False
    return bool(
        addr.is_global
        and not addr.is_private
        and not addr.is_loopback
        and not addr.is_link_local
        and not addr.is_multicast
        and not addr.is_reserved
        and not addr.is_unspecified
    )

