from typing import Callable
from urllib.parse import urljoin, urlparse
from pkg_ar35.ip_policy import is_public_ip

def _check_single_url(target_url: str, resolver: Callable[[str], list[str]]) -> str:
    parsed = urlparse(target_url.strip())
    if parsed.scheme.lower() != 'https' or not parsed.hostname:
        raise PermissionError(f'HTTPS host required: {target_url!r}')
    if parsed.username is not None or parsed.password is not None:
        raise PermissionError('Embedded URL userinfo credentials forbidden')
    addrs = resolver(parsed.hostname)
    if not addrs:
        raise PermissionError(f'Unresolvable host: {parsed.hostname!r}')
    for ip_str in addrs:
        if not is_public_ip(ip_str):
            raise PermissionError(f'Blocked non-public IP {ip_str!r} for {parsed.hostname!r}')
    return target_url.strip()

def validate_webhook_target(
    url: str,
    resolver: Callable[[str], list[str]],
    redirect_url: str | None = None,
) -> str:
    """Enforce https, reject userinfo, validate resolved IPs, and re-validate redirect targets."""
    checked = _check_single_url(url, resolver)
    if redirect_url is not None:
        resolved_hop = urljoin(checked, redirect_url)
        return _check_single_url(resolved_hop, resolver)
    return checked

